// END GUIDES

function openGuide(pluginId) {
  const guide = guides[pluginId];
  if (!guide) {
    console.warn('No guide found for:', pluginId);
    return;
  }

  const modalBody = document.getElementById('modal-body');
  let html = '<div class="guide-header"><span class="guide-category">' + guide.category + '</span><h3>' + guide.title + '</h3><p>' + guide.subtitle + '</p></div>';

  html += '<div class="guide-body">';

  if (guide.video) {
    // the presentation video: the plugin playing the demo loop, before and after (poster: a still of it)
    html += '<video class="guide-shot guide-video" src="' + guide.video + '" poster="' + guide.video.replace(/\.mp4$/, '.jpg') + '" controls playsinline preload="none" width="1280" height="720" aria-label="' + guide.title + ' presentation video"></video>';
  } else if (guide.shot) {
    html += '<img class="guide-shot" src="' + guide.shot + '" alt="' + guide.title + ' GFX, VST3 and CLAP interface" width="720" height="480" loading="lazy">';
  }

  html += '<div class="guide-section"><h4>Controls</h4><ul class="guide-sliders">';
  guide.sliders.forEach(function(slider) {
    html += '<li><span class="slider-name">' + slider.name + '</span><span class="slider-desc">' + slider.range + ' — ' + slider.desc + '</span></li>';
  });
  html += '</ul></div>';

  html += '<div class="guide-section"><h4>Best Uses</h4><ul class="use-cases">';
  guide.uses.forEach(function(use) {
    html += '<li>' + use + '</li>';
  });
  html += '</ul></div>';

  html += '<div class="guide-section"><h4>Properties</h4><p style="font-size:12px;color:#999;">' + guide.properties + '</p></div>';

  const formatNames = {
    JSFX: 'JSFX for REAPER, with REAPER\'s own sliders',
    GFX: 'JSFX GFX for REAPER, with its own interface',
    VST3: 'VST3 for any DAW',
    CLAP: 'CLAP for any DAW'
  };
  html += '<div class="guide-section"><h4>Formats</h4><ul class="guide-formats">';
  (guide.formats || ['JSFX']).forEach(function(f) {
    html += '<li><span class="format-tag">' + f + '</span>' + formatNames[f] + '</li>';
  });
  html += '</ul></div>';

  if (guide.studio) {
    html += '<div class="guide-section"><h4>Try it</h4><a class="try-studio guide-studio" href="https://useoros.online/studio/" target="_blank" rel="noopener">'
      + '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="10"/><polygon points="10 8 16 12 10 16 10 8" fill="currentColor"/></svg>'
      + '<span class="try-studio-text"><b>Try it on orOS Studio</b><small>Add it to a track in your browser, with its own interface. Nothing to install.</small></span>'
      + '<svg class="try-studio-arrow" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M7 17 17 7"/><path d="M8 7h9v9"/></svg></a></div>';
  }

  html += '</div>';

  modalBody.innerHTML = html;
  document.getElementById('guide-modal').classList.add('active');
}

function closeModal() {
  document.querySelectorAll('#modal-body video').forEach(function(v) { v.pause(); });
  document.getElementById('guide-modal').classList.remove('active');
}

document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    closeModal();
  }
});

document.getElementById('guide-modal').addEventListener('click', function(e) {
  if (e.target === this) {
    closeModal();
  }
});

console.log('NULL JSFX Guides loaded:', Object.keys(guides).length, 'plugins');